select m.id,v.k,v.t,v.ft,v.r,v.s,v.o::jsonb from platform_modules m cross join (values
('report-code','کد گزارش','text',true,10,'{}'),('report-title','عنوان گزارش','text',true,20,'{}'),('report-type','نوع گزارش','select',true,30,'{"options":["ممیزی دسترسی","ممیزی تغییرات","ممیزی انتشار","ممیزی بایگانی","ممیزی امحا","ممیزی گردش سند","گزارش جامع"]}'),('document-code','کد سند','text',false,40,'{}'),('scope','دامنه گزارش','select',true,50,'{"options":["یک سند","گروه اسناد","پوشه","واحد سازمانی","کل سازمان"]}'),('scope-reference','مرجع دامنه','text',false,60,'{}'),('date-from','از تاریخ','text',true,70,'{}'),('date-to','تا تاریخ','text',true,80,'{}'),('actor','کاربر / عامل','text',false,90,'{}'),('event-type','نوع رویداد','select',false,100,'{"options":["مشاهده","دانلود","چاپ","اشتراک‌گذاری","ویرایش","تأیید","انتشار","بایگانی","بازگردانی","امحا","تلاش ناموفق"]}'),('result-filter','نتیجه رویداد','select',false,110,'{"options":["همه","موفق","رد شده","ناموفق"]}'),('risk-level','سطح ریسک','select',true,120,'{"options":["عادی","کم","متوسط","زیاد","بحرانی"]}'),('report-status','وضعیت گزارش','select',true,130,'{"options":["پیش‌نویس","در حال تولید","تولید شده","بازبینی شده","تأیید شده","آرشیو شده"]}'),('generated-at','تاریخ تولید','text',false,140,'{}'),('generated-by','تولیدکننده','text',false,150,'{}'),('result-reference','مرجع نتایج','text',false,160,'{}'),('finding-summary','خلاصه یافته‌ها','textarea',false,170,'{}'),('recommendations','اقدامات پیشنهادی','textarea',false,180,'{}'),('notes','یادداشت','textarea',false,190,'{}')
) v(k,t,ft,r,s,o) where m.code='48-document-audit-reports' on conflict(module_id,field_key) do update set title=excluded.title,field_type=excluded.field_type,required=excluded.required,sort_order=excluded.sort_order,options=excluded.options;
