insert into platform_modules(code,title,is_active) values ('48-document-audit-reports','گزارش‌های ممیزی مستندات',true) on conflict(code) do update set title=excluded.title,is_active=true;
insert into module_field_definitions(module_id,field_key,title,field_type,required,sort_order,options)
insert into module_actions(module_id,action_code,title,permission) select m.id,v.a,v.t,v.p from platform_modules m cross join (values
('read','مشاهده گزارش‌ها','modules:48-document-audit-reports:read'),('write','ثبت گزارش','modules:48-document-audit-reports:write'),('delete','حذف گزارش','modules:48-document-audit-reports:delete'),('generate','تولید گزارش','modules:48-document-audit-reports:generate'),('review','بازبینی گزارش','modules:48-document-audit-reports:review'),('approve','تأیید گزارش','modules:48-document-audit-reports:approve'),('archive','بایگانی گزارش','modules:48-document-audit-reports:archive')) v(a,t,p) where m.code='48-document-audit-reports' on conflict(module_id,action_code) do update set title=excluded.title,permission=excluded.permission;